    61	// processStartTime is field 22 of /proc/<pid>/stat: the start time of the
    62	// process in clock ticks since boot. It is read after the command name,
    63	// which may itself contain spaces and parentheses.
    64	func processStartTime(pid int) (string, error) {
    65		raw, err := os.ReadFile(fmt.Sprintf("/proc/%d/stat", pid))
    66		if err != nil {
    67			return "", err
    68		}
    69		text := string(raw)
    70		end := strings.LastIndexByte(text, ')')
    71		if end < 0 {
    72			return "", fmt.Errorf("unreadable stat")
    73		}
    74		fields := strings.Fields(text[end+1:])
    75		// fields[0] is field 3 (state); the start time is field 22.
    76		if len(fields) < 20 {
    77			return "", fmt.Errorf("unreadable stat")
    78		}
    79		return fields[19], nil
    80	}
